mapper.insert:
INSERT INTO PDS (
      pds_id
    , title
    , title_no_space
    , substance
    , attach_file_count
    , create_user_id
    , created_at
    , changed_at
) VALUES (
      #{pdsId}
    , #{title}
    , #{titleNoSpace}
    , #{substance}
    , (SELECT COUNT(*) FROM PDS_FILE k WHERE k.pds_id = #{pdsId})
    , #{createUserId}
    , #{createdAt}
    , #{changedAt}
)

mapper.update:
UPDATE PDS
   SET title              = #{title}
     , title_no_space     = #{titleNoSpace}
     , substance          = #{substance}
     , attach_file_count  = (SELECT COUNT(*) FROM PDS_FILE k WHERE k.pds_id = #{pdsId})
     , changed_at         = CURRENT_TIMESTAMP
 WHERE pds_id  = #{pdsId}

mapper.select:
SELECT t.* FROM ( SELECT a.* , ROWNUM AS RN FROM ( SELECT z.* FROM PDS z
and z.location = 'BASIC'
ORDER BY z.created_at DESC ) a WHERE ROWNUM <= (#{pageNumber} + 1) * #{rowsPerPage} ) t WHERE RN > #{pageNumber} * #{rowsPerPage}

SELECT t.* FROM ( SELECT a.* , ROWNUM AS RN FROM ( SELECT z.* FROM PDS z
and z.location = 'DOC'
ORDER BY z.created_at DESC ) a WHERE ROWNUM <= (#{pageNumber} + 1) * #{rowsPerPage} ) t WHERE RN > #{pageNumber} * #{rowsPerPage}
